package main

import (
	"strings"
	"testing"
)

// Two implementations of counting vowels

// countVowelsLoop uses a loop
func countVowelsLoop(s string) int {
	count := 0
	for _, c := range strings.ToLower(s) {
		switch c {
		case 'a', 'e', 'i', 'o', 'u':
			count++
		}
	}
	return count
}

// countVowelsMap uses a map lookup
func countVowelsMap(s string) int {
	vowels := map[rune]bool{'a': true, 'e': true, 'i': true, 'o': true, 'u': true}
	count := 0
	for _, c := range strings.ToLower(s) {
		if vowels[c] {
			count++
		}
	}
	return count
}

